/**
 * Daily throttle ("cost airbag"). Counts how many tickets were created today
 * using n8n's persistent workflow static data. Resets automatically each day.
 * Limit = 10 per day. Runs BEFORE the Groq call so no AI cost is incurred once
 * the limit is reached.
 */
const LIMIT = 10;
const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);

if (staticData.counterDate !== today) {
  staticData.counterDate = today;
  staticData.counter = 0;
}

const used = staticData.counter || 0;
const limitReached = used >= LIMIT;

return [{
  json: {
    ...$input.item.json,
    throttle: { used, limit: LIMIT, limitReached },
  },
}];

/**
 * Assembles a Join-compatible task.
 * - title: from the AI (short, in the email's language)
 * - description: VERBATIM from the original email (never AI-rewritten/translated)
 * - category / priority / dueDate / subtasks: classified by the AI
 * - creator: the sender, marked as external
 * Also repairs UTF-8/Latin-1 mojibake (Ã¤ -> ä) that some mail servers produce.
 */

function fixEncoding(text) {
  if (!text) return '';
  if (!/Ã|Â/.test(text)) return text;
  try {
    return Buffer.from(text, 'latin1').toString('utf8');
  } catch (e) {
    return text;
  }
}

// 1) Parse the AI answer (strip fences / think tags defensively)
const raw = $json.choices[0].message.content || '';
const cleaned = raw
  .replace(/```json|```/g, '')
  .replace(/<think>[\s\S]*?<\/think>/g, '')
  .trim();

let ai;
try {
  ai = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI did not return valid JSON: ' + raw);
}

// 2) Original email parts (from the Edit Fields node), encoding-repaired
const senderEmail = fixEncoding($('Extracts email metadata and content for further processing').item.json.senderEmail || '');
const senderName  = fixEncoding($('Extracts email metadata and content for further processing').item.json.senderName || '');
const emailText   = fixEncoding($('Extracts email metadata and content for further processing').item.json.emailText || '');

// 3) Description = original email body (verbatim), without the "Betreff:" line
const lines = emailText.split('\n');
const bodyText = lines.slice(1).join('\n').trim();
const description = (bodyText || emailText).trim() + '\n— Dieses Ticket wurde KI-generiert.';

// 4) Title from AI (also encoding-repaired), fallback to subject line
const subjectLine = (lines[0] || '').replace(/^Betreff:\s*/i, '').trim();
const title = fixEncoding((ai.title && String(ai.title).trim()) || subjectLine || 'Anfrage');

// 5) Validate the AI's classification values
const priority = ['Urgent', 'Medium', 'Low'].includes(ai.priority) ? ai.priority : 'Medium';
const category = ai.category === 'Technical Tasks' ? 'Technical Tasks' : 'User Story';
const dueDate  = typeof ai.dueDate === 'string' ? ai.dueDate : '';

// 6) Extract and normalize subtasks from AI response
const rawSubtasks = Array.isArray(ai.subtasks) ? ai.subtasks : [];
const subtasks = rawSubtasks
  .map(s => {
    if (!s) return null;
    if (typeof s === 'string') {
      const t = s.trim();
      return t ? { title: t, done: false } : null;
    }
    const t = String(s.title || s.text || s.name || '').trim();
    return t ? { title: t, done: !!(s.done || s.checked || s.completed) } : null;
  })
  .filter(Boolean);

// 7) Build the full task object
const task = {
  title,
  description,
  dueDate,
  priority,
  category,
  status: 'triage',
  assignedTo: [],
  subtasks,
  creator: { name: senderName, email: senderEmail, type: 'external' },
  isAiGenerated: true,
};

return [{ json: { task } }];

/**
 * Increments the daily counter after a ticket was successfully created.
 * Also writes the current count to Firebase so the Landing Page can
 * display it live without needing access to n8n directly.
 */
const LIMIT = 10;
const FIREBASE_URL = "https://join-60a91-default-rtdb.europe-west1.firebasedatabase.app";

const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);

if (staticData.counterDate !== today) {
  staticData.counterDate = today;
  staticData.counter = 0;
}
staticData.counter = (staticData.counter || 0) + 1;

const used = staticData.counter;
const remaining = Math.max(0, LIMIT - used);

await this.helpers.httpRequest({
  method: 'PUT',
  url: `${FIREBASE_URL}/dailyCounter.json`,
  body: {
    date: today,
    used,
    remaining,
    limit: LIMIT,
  },
  json: true,
});

return [{ json: { counter: used, remaining } }];

/**
 * Erstellt den Request-Body für die Groq API als sauberes Objekt.
 */

const emailText = $json.emailText || '';
const today = new Date().toISOString().slice(0, 10);

const systemPrompt =
  "Du bist ein Triage-Assistent für das Join-Kanban-Board. Du erhältst eine E-Mail und gibst AUSSCHLIESSLICH ein strikt gültiges JSON-Objekt zurück (keine Einleitung, keine Erklärung, kein Markdown) mit genau fünf Feldern: title, category, priority, dueDate, subtasks. " +
  "REGELN: title = ein kurzer, klarer Ticket-Titel mit maximal ca. 60 Zeichen, geschrieben in GENAU DERSELBEN SPRACHE wie die E-Mail (eine deutsche E-Mail erhält einen deutschen Titel, niemals übersetzen). " +
  "category = exakt 'Technical Tasks' oder 'User Story' ('User Story' für Funktionswünsche oder Benutzeranforderungen, 'Technical Tasks' für Fehler, Abstürze, Bugs oder Backend-Arbeiten). " +
  "priority = exakt 'Urgent', 'Medium' oder 'Low'. Wähle Urgent bei hoher Wichtigkeit oder Dringlichkeit in jeder Sprache, z. B. Deutsch: dringend, sehr wichtig, wichtig, sofort, so schnell wie möglich, kritisch, blockiert, Ausfall, Notfall, eilt; oder Englisch: urgent, asap, critical, blocker, broken, crash, production down, security, data loss. " +
  "Wähle Low für: nice to have, wäre schön, kein Stress, irgendwann, Kleinigkeit, kosmetisch, unwichtig, minor, no rush. Wähle Medium nur dann, wenn kein klares Signal vorhanden ist. " +
  "dueDate = 'YYYY-MM-DD', wenn ein Termin erwähnt oder impliziert wird (z. B. 'bis Ende Monat', 'bis am 15. Juli'), aufgelöst anhand des heutigen Datums " + today + ", ansonsten ein leerer String ''. " +
  "subtasks = ein Array von Objekten mit den Feldern 'title' (string) und 'done' (false). Extrahiere als Subtasks alle aufgezählten Punkte aus der E-Mail. Erkenne: Ordinale auf Deutsch (erstens, zweitens, drittens ...), Ordinale auf Englisch (firstly, secondly, thirdly ...), nummerierte Listen (1. 2. 3. oder 1) 2) 3)), sowie Zeilen die mit -, *, oder einem Aufzählungszeichen beginnen. Kürze jeden Subtask-Titel auf das Wesentliche (max. 60 Zeichen). Wenn keine Aufzählung erkennbar ist, setze subtasks als leeres Array []. " +
  "Schreibe KEINE Beschreibung.";

const userPrompt =
  "Erstelle das JSON für diese E-Mail. Der Titel MUSS in der Sprache der E-Mail sein (deutsche E-Mail = deutscher Titel, niemals übersetzen). " +
  "Achte bei der Priorität auf deutsche Dringlichkeitswörter wie 'wichtig' oder 'dringend'.\n\n--- E-MAIL ---\n" +
  emailText +
  "\n--- ENDE ---";

const requestBody = {
  model: 'llama-3.3-70b-versatile',
  temperature: 0.1,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt },
  ],
};

return [{
  json: {
    ...$json,
    groqBody: JSON.stringify(requestBody),
  },
}];
